    let currentLanguage = localStorage.getItem(LANG_STORAGE_KEY) || 'en';

    
    const CATEGORY_MAP = {
        'Food & Drink': 'cat_food_drink',
        'Transportation': 'cat_transportation',
        'Shopping': 'cat_shopping',
        'Beauty': 'cat_beauty',
        'Bills & Utilities': 'cat_bills_utilities',
        'Entertainment': 'cat_entertainment',
        'Health': 'cat_health',
        'Education': 'cat_education',
        'Salary': 'cat_salary',
        'Investment': 'cat_investment',
        'Adjustment': 'cat_adjustment',
        'Transfer': 'cat_transfer',
        'Financial Goal': 'cat_financial_goal',
        'Debt / Loan': 'cat_debt_loan',
        'Others': 'cat_others'
    };

    function translateCategory(name) {
        if (!name) return '';
        const key = CATEGORY_MAP[name];
        if (key) {
            return getTranslation(key, name);
        }
        return name;
    }

    function getCurrentLocale() {
        const langObj = LANGUAGES.find(l => l.code === currentLanguage);
        return langObj ? langObj.locale : 'en-US';
    }

    function getLanguageFlagUrl(flagCode) {
        return `https://flagcdn.com/w40/${flagCode}.png`;
    }

    
