                zh: (m) => `收据扫描成功！金额：${m[1]}`,
                ar: (m) => `تم مسح الإيصال بنجاح! المبلغ: ${m[1]}`,
                pt: (m) => `Recibo escaneado com sucesso! Valor: ${m[1]}`,
                ru: (m) => `Чек успешно отсканирован! Сумма: ${m[1]}`,
                nl: (m) => `Bon succesvol gescand! Bedrag: ${m[1]}`
